import{_ as a,o as i,c as s,a0 as t}from"./chunks/framework.DoRPXVp_.js";const g=JSON.parse('{"title":"ICE Candidate Race: P2P Handshake Timeout Fix","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0002-ice-candidate-race-fix.md","filePath":"adr/0002-ice-candidate-race-fix.md"}'),n={name:"adr/0002-ice-candidate-race-fix.md"};function o(d,e,r,l,c,p){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="ice-candidate-race-p2p-handshake-timeout-fix" tabindex="-1">ICE Candidate Race: P2P Handshake Timeout Fix <a class="header-anchor" href="#ice-candidate-race-p2p-handshake-timeout-fix" aria-label="Permalink to &quot;ICE Candidate Race: P2P Handshake Timeout Fix&quot;">​</a></h1><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>In the agent-sandbox E2E test, the WireGuard tunnel between a companion pod and a sandbox pod consistently failed to establish within the 180-second timeout. The symptom was <code>wget: download timed out</code>, caused by the ICE handshake never completing and therefore the WireGuard endpoint never being set.</p><h2 id="root-cause-analysis" tabindex="-1">Root Cause Analysis <a class="header-anchor" href="#root-cause-analysis" aria-label="Permalink to &quot;Root Cause Analysis&quot;">​</a></h2><p>The failure was caused by <strong>two independent bugs</strong> that compounded each other.</p><h3 id="bug-1-—-missing-appid-in-sandbox-latticepeer-primary-cause" tabindex="-1">Bug 1 — Missing <code>AppId</code> in sandbox LatticePeer (primary cause) <a class="header-anchor" href="#bug-1-—-missing-appid-in-sandbox-latticepeer-primary-cause" aria-label="Permalink to &quot;Bug 1 — Missing \`AppId\` in sandbox LatticePeer (primary cause)&quot;">​</a></h3><p><code>internal/server/service/agent_registration.go</code> creates the LatticePeer CRD when a sandbox agent enrolls. The original code did <strong>not</strong> set <code>Spec.AppId</code>:</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Before</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Spec: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">v1alpha1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LatticePeerSpec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PublicKey: req.PublicKey,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Network:   networkRef,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // AppId omitted</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p><code>LatticePeerSpec.AppId</code> carries <code>json:&quot;appId,omitempty&quot;</code>, so a zero-value <code>&quot;&quot;</code> is silently dropped when the controller serialises the peer list into the ConfigMap. The companion receives a <code>computedpeers</code> entry with no <code>appId</code> field:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sandbox-xxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;address&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10.0.5.3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;publicKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RWcG...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;peerId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000973369834774145</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="bug-2-—-ice-candidates-arriving-before-the-agent-is-initialised-secondary-cause" tabindex="-1">Bug 2 — ICE candidates arriving before the agent is initialised (secondary cause) <a class="header-anchor" href="#bug-2-—-ice-candidates-arriving-before-the-agent-is-initialised-secondary-cause" aria-label="Permalink to &quot;Bug 2 — ICE candidates arriving before the agent is initialised (secondary cause)&quot;">​</a></h3><p>ICE signalling is asymmetric: the non-initiator (sandbox) may send OFFER candidates before the initiator (companion) has finished constructing its <code>ice.Agent</code> inside <code>Prepare()</code>. The original <code>Handle()</code> returned early when <code>i.agent == nil</code>, silently discarding those candidates.</p><h3 id="how-the-two-bugs-interact" tabindex="-1">How the two bugs interact <a class="header-anchor" href="#how-the-two-bugs-interact" aria-label="Permalink to &quot;How the two bugs interact&quot;">​</a></h3><ol><li>Companion receives <code>appId=&quot;&quot;</code> for the sandbox → <code>peerManager.AddPeer(&quot;&quot;, peer)</code> → probe <strong>P1</strong> created with key <code>&quot;&quot;</code> → <code>Prepare()</code> builds ICE agent <strong>A1</strong>, starts gathering.</li><li>Sandbox sends ACK carrying <code>appId=&quot;sandbox-xxx&quot;</code> → <code>onPeerReceived</code> updates <code>byID</code> to point to the peer with the correct AppID.</li><li>Sandbox sends ICE OFFER → <code>ProbeFactory.Handle()</code> calls <code>GetIdentity(peerID)</code> → resolves to <code>AppID=&quot;sandbox-xxx&quot;</code> → <code>Get(&quot;sandbox-xxx&quot;)</code> → <strong>not found</strong> → creates new probe <strong>P2</strong> (no ICE agent).</li><li>P2 receives the OFFER but has <code>agent == nil</code> — candidate is buffered but never processed.</li><li>P1&#39;s <code>Dial()</code> blocks on <code>offerReady</code> channel which never closes → 65-second timeout.</li><li>After the 60-second unreachability threshold, the probe is closed → E2E test fails.</li></ol><p>The log evidence confirmed the sequence:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>peer known, pre-configured WG entry  remoteId=&quot;&quot;              allowedIPs=10.0.5.3/32  (P1 created)</span></span>
<span class="line"><span>peer known, pre-configured WG entry  remoteId=sandbox-xxx     allowedIPs=10.0.5.3/32  (P2 created)</span></span>
<span class="line"><span>receive offer: agent not ready, buffering candidate                                    (P2, no agent)</span></span>
<span class="line"><span>iceDialer: timed out waiting for offer                                                 (P1 times out)</span></span>
<span class="line"><span>peer unreachable for 60s, closing probe</span></span></code></pre></div><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><h3 id="fix-1-—-set-appid-at-enrollment-agent-registration-go" tabindex="-1">Fix 1 — Set <code>AppId</code> at enrollment (<code>agent_registration.go</code>) <a class="header-anchor" href="#fix-1-—-set-appid-at-enrollment-agent-registration-go" aria-label="Permalink to &quot;Fix 1 — Set \`AppId\` at enrollment (\`agent_registration.go\`)&quot;">​</a></h3><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Spec: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">v1alpha1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LatticePeerSpec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AppId:     req.AgentName,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// always set so ConfigMap JSON includes appId</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PublicKey: req.PublicKey,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Network:   networkRef,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p>This ensures the ConfigMap always serialises a non-empty <code>appId</code> matching the peer <code>name</code>, eliminating the probe key mismatch entirely.</p><h3 id="fix-2-—-defensive-fallback-in-transfertopeer-controller-utils-go" tabindex="-1">Fix 2 — Defensive fallback in <code>transferToPeer</code> (<code>controller/utils.go</code>) <a class="header-anchor" href="#fix-2-—-defensive-fallback-in-transfertopeer-controller-utils-go" aria-label="Permalink to &quot;Fix 2 — Defensive fallback in \`transferToPeer\` (\`controller/utils.go\`)&quot;">​</a></h3><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">appID </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> peer.Spec.AppId</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appID </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    appID </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> peer.Name</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Guards against any existing or future LatticePeer that reaches the controller without <code>Spec.AppId</code> set (e.g. hand-crafted CRDs, older manifests).</p><h3 id="fix-3-—-buffer-and-replay-ice-candidates-ice-dialer-go" tabindex="-1">Fix 3 — Buffer and replay ICE candidates (<code>ice_dialer.go</code>) <a class="header-anchor" href="#fix-3-—-buffer-and-replay-ice-candidates-ice-dialer-go" aria-label="Permalink to &quot;Fix 3 — Buffer and replay ICE candidates (\`ice_dialer.go\`)&quot;">​</a></h3><ul><li><code>Handle(OFFER)</code> appends candidates to <code>pendingCandidates</code> when <code>agent == nil</code> instead of dropping them.</li><li><code>Prepare()</code> drains <code>pendingCandidates</code> into the newly created agent after <code>i.agent</code> is set.</li><li><code>GatherCandidates</code> is guarded with a <code>sync.Once</code> (<code>gatherOnce</code>) so it is called exactly once even when an ACK races ahead of the agent initialisation and re-triggers the gather path.</li></ul><h2 id="affected-files" tabindex="-1">Affected Files <a class="header-anchor" href="#affected-files" aria-label="Permalink to &quot;Affected Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td><code>internal/server/service/agent_registration.go</code></td><td>Set <code>Spec.AppId = req.AgentName</code></td></tr><tr><td><code>internal/agent/controller/utils.go</code></td><td>Fallback <code>AppId → Name</code> in <code>transferToPeer</code></td></tr><tr><td><code>internal/server/transport/ice_dialer.go</code></td><td>Buffer/replay candidates; <code>sync.Once</code> for <code>GatherCandidates</code></td></tr></tbody></table><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Sandbox peers now always appear with a stable, non-empty <code>appId</code> in the network ConfigMap.</li><li>ICE candidates sent before the local agent is ready are no longer silently dropped; they are replayed immediately after <code>Prepare()</code> completes.</li><li>The <code>ProbeFactory</code> will never create a duplicate probe for the same physical peer due to an <code>appId</code>/<code>name</code> mismatch.</li></ul>`,29)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
